// The expedition member: kit-bashed from text-grid parts (head/hood, torso, legs generated by a tiny walk-cycle rig), outlined and cached per
// (pose, look, rime). The near arm and the held tool are drawn dynamically so tools can rotate toward the aim.
// Local coordinates in this file: origin = feet centre, +x forward (facing), +y down. Raw grid 12×20; outlined sprite 14×21 (anchor 7,21).
import { compose, outline, rowsCanvas, newCanvas, silhouette, drawSprite, drawFlame, type Rows, type Palette } from '../engine/sprites';
import { Grid } from './grid';
import { HELD } from './tools';

export interface Look { parka: 'station' | 'fur'; head: 'none' | 'hat' | 'fur'; hands: 'wool' | 'fur'; feet: 'felt' | 'kamik' }
export const DEFAULT_LOOK: Look = { parka: 'station', head: 'hat', hands: 'wool', feet: 'felt' };
export const lookKey = (l: Look) => l.parka[0] + l.head[0] + l.hands[0] + l.feet[0];
/** Map the inventory's worn item ids to a Look. */
export function lookFromWear(w: { head?: string | null; body?: string | null; hands?: string | null; feet?: string | null }): Look {
  return {
    parka: w.body === 'fur_parka' ? 'fur' : 'station',
    head: w.head === 'fur_hood' ? 'fur' : w.head === 'wool_hat' ? 'hat' : 'none',
    hands: w.hands === 'fur_mittens' ? 'fur' : 'wool',
    feet: w.feet === 'kamiks' ? 'kamik' : 'felt',
  };
}

function palette(l: Look): Palette {
  const fur = l.parka === 'fur', fh = l.head === 'fur';
  return {
    K: '#231a2b',
    r: fur ? '#b08f66' : '#e4492d', R: fur ? '#70593f' : '#a42b27', o: fur ? '#e3cfa4' : '#f7902f',
    h: fh ? '#6d5444' : fur ? '#b08f66' : '#e4492d', H: fh ? '#4b3a2f' : fur ? '#70593f' : '#a42b27',
    c: fh ? '#e0d4be' : '#f3ead7', C: fh ? '#a99a7c' : '#cbbd9e',
    f: '#efbd99', F: '#c08566', k: '#2a2030',
    l: '#3c4464', L: '#272c47',
    b: l.feet === 'kamik' ? '#4a3630' : '#94826e', B: l.feet === 'kamik' ? '#271b19' : '#5d4e41', x: l.feet === 'kamik' ? '#ece2cc' : '#bcab91',
    m: l.hands === 'fur' ? '#dcc9a6' : '#8f9cb3', M: l.hands === 'fur' ? '#9c8662' : '#5d6881',
    t: '#6e4727', y: '#ecc95c', q: '#3f8ca4', Q: '#a3d6e0', n: '#f6fcff', i: '#bfe2f7', z: '#cfe4f4',
  };
}

// ---- parts ---------------------------------------------------------------------------------------------------------------------------
const HEAD_BASE: Rows = [
  '..hhhhh..',
  '.hhhhhhc.',
  'hhhhhcccc',
  'hhhhhcffc',
  'hhhhhcfkc',
  'hhhhHcFfc',
  '.HHHHCccc',
  '..HHCCCC.',
];
const HEAD_HAT: Rows = [
  '..hhhhh..',
  '.hhhhhhq.',
  'hhhhhqQqq',
  'hhhhhcffc',
  'hhhhhcfkc',
  'hhhhHcFfc',
  '.HHHHCccc',
  '..HHCCCC.',
];
const HEAD_FUR: Rows = [
  '..hhhhh..',
  '.hhhhhhcc',
  'hhhhhhccc',
  'hhhhhcffc',
  'hhhhhcfkc',
  'hhhhHckkc',
  '.HHHHCkcc',
  '..HHCCCC.',
];
const TORSO_STATION: Rows = [
  '.Rrrrrr.',
  'Rrrrrrrr',
  'Rrrrrrrr',
  'RooooooR',
  'Rrrrrrrr',
  'ttttttyt',
  'RRRRRRRR',
];
const TORSO_FUR: Rows = [
  '.Rrrrrr.',
  'Rrrrrrrr',
  'RrRrrrRr',
  'Rrrrrrrr',
  'rRrrrRrr',
  'ttttttyt',
  'ooRooRoo',
];

type LegDef = [number, number, number, number]; // back foot dx, back lift, front foot dx, front lift
export const LEGS: Record<string, LegDef> = {
  stand: [0, 0, 0, 0],
  walk0: [-2, 0, 2, 0], walk1: [0, 1, 0, 0], walk2: [2, 0, -2, 0], walk3: [0, 0, 0, 1],
  run0: [-3, 2, 3, 0], run1: [-1, 3, 1, 2], run2: [3, 0, -3, 2], run3: [1, 2, -1, 3],
  jump: [-1, 2, 2, 3], fall: [-2, 1, 3, 1], kick0: [-1, 0, 1, 2], kick1: [1, 2, -1, 0],
};

function legsGrid(g: Grid, d: LegDef) {
  const leg = (hx: number, fx: number, lift: number, back: boolean) => {
    const bt = 17 - lift;
    g.line(hx, 14, fx + 1, bt - 1, back ? 'L' : 'l', 2);
    g.line(hx, 15, fx + 1, bt - 1, back ? 'L' : 'l', 2);
    for (let i = 0; i < 3; i++) g.set(fx + i, bt, 'x');
    for (let i = 0; i < 4; i++) { g.set(fx + i, bt + 1, back ? 'B' : 'b'); g.set(fx + i, bt + 2, 'B'); }
    if (back) { g.set(fx, bt + 1, 'B'); }
  };
  leg(5, 3 + d[0], d[1], true);
  leg(6, 5 + d[2], d[3], false);
}

export type FarArm = 'down' | 'fwd' | 'back' | 'up' | 'hug';
const FAR_HAND: Record<FarArm, [number, number]> = { down: [5, 13], fwd: [9, 12], back: [2, 12], up: [4, 0], hug: [8, 10] };

function rimeHead(head: Rows, level: number): Rows {
  if (!level) return head;
  return head.map((r, y) => r.replace(/./g, (ch, x) => {
    if (ch === 'c') return level >= 2 || (x + y) % 2 === 0 ? 'n' : ch;
    if (ch === 'C') return level >= 2 ? 'i' : ch;
    if (ch === 'h' && y === 0 && level >= 1 && x % 2 === 0) return 'i';
    if (ch === 'h' && level >= 2 && y <= 1 && (x + y) % 3 === 0) return 'n';
    return ch;
  }));
}

function rawBody(look: Look, legs: string, lean: number, headDy: number, far: FarArm, rime: number, torsoDy = 0): Rows {
  const g = new Grid(12, 20);
  const [fx, fy] = FAR_HAND[far];
  g.line(6, 9 + torsoDy, fx + 2, fy, 'R', 2);
  g.rect(fx + 1, fy, 2, 2, 'M'); g.rect(fx + 1, fy, 2, 1, 'm');
  legsGrid(g, LEGS[legs] ?? LEGS.stand);
  g.blit(look.parka === 'fur' ? TORSO_FUR : TORSO_STATION, 2 + (lean > 0 ? 1 : 0), 7 + torsoDy);
  const head = look.head === 'hat' ? HEAD_HAT : look.head === 'fur' ? HEAD_FUR : HEAD_BASE;
  g.blit(rimeHead(head, rime), 3 + lean, headDy);
  return g.rows();
}

const bodyCache = new Map<string, HTMLCanvasElement>();
const silCache = new Map<HTMLCanvasElement, HTMLCanvasElement>();
export interface BodyKey { legs: string; lean: number; headDy: number; far: FarArm; rime: number; torsoDy: number }
function bodyCanvas(look: Look, k: BodyKey): HTMLCanvasElement {
  const key = lookKey(look) + '|' + k.legs + '|' + k.lean + '|' + k.headDy + '|' + k.far + '|' + k.rime + '|' + k.torsoDy;
  let c = bodyCache.get(key); if (c) return c;
  const rows = outline(rawBody(look, k.legs, k.lean, k.headDy, k.far, k.rime, k.torsoDy));
  c = rowsCanvas(rows.slice(0, rows.length - 1), palette(look));
  if (bodyCache.size > 500) bodyCache.clear();
  bodyCache.set(key, c); return c;
}

// ---- lying poses (sleep / dead): the standing body rotated 90° ------------------------------------------------------------------------
function rotCW(rows: Rows): Rows { const h = rows.length, w = rows[0].length; const o: string[] = []; for (let x = 0; x < w; x++) { let s = ''; for (let y = h - 1; y >= 0; y--) s += rows[y][x]; o.push(s); } return o; }
function rotCCW(rows: Rows): Rows { const h = rows.length, w = rows[0].length; const o: string[] = []; for (let x = w - 1; x >= 0; x--) { let s = ''; for (let y = 0; y < h; y++) s += rows[y][x]; o.push(s); } return o; }
const lyingCache = new Map<string, HTMLCanvasElement>();
/** Lying body, head toward +x. kind 'sleep' = on the back with a blanket pulled up; 'dead' = face down. Anchor: bottom-centre. */
function lyingCanvas(look: Look, kind: 'sleep' | 'dead', rime: number): HTMLCanvasElement {
  const key = kind + lookKey(look) + rime;
  let c = lyingCache.get(key); if (c) return c;
  const raw = rawBody(look, 'stand', 0, 0, kind === 'sleep' ? 'hug' : 'fwd', rime);
  let rows = kind === 'sleep' ? rotCCW(raw).map(r => r.split('').reverse().join('')) : rotCW(raw);
  if (kind === 'sleep') {
    // blanket over everything but the head: columns from the feet up to the neck
    const g = new Grid(rows[0].length, rows.length); g.blit(rows, 0, 0);
    const neck = rows[0].length - 11;
    for (let y = 0; y < rows.length; y++) for (let x = 0; x < neck; x++) if (g.get(x, y) !== '.') g.set(x, y, (x + y) % 4 < 2 ? 'Q' : 'q');
    for (let x = 0; x < neck; x++) g.set(x, 2, 'i'), g.set(x, 3, 'n');
    rows = g.rows();
  }
  const o = outline(rows);
  c = rowsCanvas(o.slice(0, o.length - 1), palette(look));
  lyingCache.set(key, c); return c;
}

// ---- pose model -----------------------------------------------------------------------------------------------------------------------
export interface ToolSpec { item: string; ang: number; reach: number; load: number; flipY: boolean; using: boolean; t: number }
export interface PoseSpec {
  face: 1 | -1;
  legs: string; dy: number; lean: number; headDy: number; torsoDy: number;
  far: FarArm;
  hand: [number, number] | null;      // near hand, local coords; null = hang
  armBehind: boolean;
  tool: ToolSpec | null;
  rime: 0 | 1 | 2;
  clipH: number | null;               // waterline height above the feet
  lying: 'sleep' | 'dead' | null;
  hurt: boolean;
  carry: boolean;
  shakeX: number;
  t: number;
}
export const newPose = (): PoseSpec => ({ face: 1, legs: 'stand', dy: 0, lean: 0, headDy: 0, torsoDy: 0, far: 'down', hand: null, armBehind: false, tool: null, rime: 0, clipH: null, lying: null, hurt: false, carry: false, shakeX: 0, t: 0 });

const SH_X = 0, SH_Y = -11;            // near shoulder (local)
const ARM_LEN = 5;

function pixelRect(ctx: CanvasRenderingContext2D, col: string, x: number, y: number, w = 1, h = 1) { ctx.fillStyle = col; ctx.fillRect(x, y, w, h); }
/** Outlined 2-cell-thick arm from the shoulder to the hand + mitten. Local coordinates (ctx already translated/flipped). */
function drawArm(ctx: CanvasRenderingContext2D, look: Look, sx: number, sy: number, hx: number, hy: number, pal: Palette) {
  const pts: [number, number][] = [];
  const n = Math.max(Math.abs(hx - sx), Math.abs(hy - sy), 1);
  for (let i = 0; i <= n; i++) {
    const x = Math.round(sx + (hx - sx) * i / n), y = Math.round(sy + (hy - sy) * i / n);
    pts.push([x, y]);
    if (Math.abs(hx - sx) > Math.abs(hy - sy)) pts.push([x, y + 1]); else pts.push([x + 1, y]);
  }
  const set = new Set(pts.map(p => p[0] + ',' + p[1]));
  const mit = look.hands === 'fur' ? 3 : 2;
  const mx = Math.round(hx) - (mit === 3 ? 1 : 0), my = Math.round(hy) - (mit === 3 ? 1 : 0);
  for (let j = -1; j <= mit; j++) for (let i = -1; i <= mit; i++) if (i < 0 || j < 0 || i >= mit || j >= mit) set.add((mx + i) + ',' + (my + j));
  // outline pass (every cell 4-adjacent to a body cell that is not in the set)
  ctx.fillStyle = pal.K;
  const body = new Set(pts.map(p => p[0] + ',' + p[1]));
  for (let j = 0; j < mit; j++) for (let i = 0; i < mit; i++) body.add((mx + i) + ',' + (my + j));
  for (const key of body) { const [x, y] = key.split(',').map(Number); for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (!body.has((x + dx) + ',' + (y + dy))) ctx.fillRect(x + dx, y + dy, 1, 1); }
  for (const [x, y] of pts) pixelRect(ctx, pal.r, x, y);
  for (let i = Math.max(0, pts.length - 3); i < pts.length; i++) pixelRect(ctx, pal.R, pts[i][0], pts[i][1]);
  for (let j = 0; j < mit; j++) for (let i = 0; i < mit; i++) pixelRect(ctx, j === mit - 1 || i === 0 ? pal.M : pal.m, mx + i, my + j);
}

const ang2 = (a: number) => Math.round(a / (Math.PI / 12)) * (Math.PI / 12);
/** One swing cycle for chop-like tools. phase 0..1 → angle offset (radians, negative = tool raised) and torso lean. */
function swingOffset(phase: number, kind: string): { off: number; lean: number; reach: number } {
  if (kind === 'thrust') { const r = phase < 0.35 ? -3 * (phase / 0.35) : phase < 0.6 ? -3 + 7.5 * ((phase - 0.35) / 0.25) : 4.5 * (1 - (phase - 0.6) / 0.4); return { off: 0, lean: phase > 0.35 && phase < 0.75 ? 1 : 0, reach: r }; }
  if (kind === 'dig') { const o = phase < 0.3 ? -0.9 - 0.3 * (phase / 0.3) : phase < 0.55 ? -1.2 + 1.9 * ((phase - 0.3) / 0.25) : 0.7 * (1 - (phase - 0.55) / 0.45); return { off: o, lean: phase > 0.3 && phase < 0.7 ? 1 : 0, reach: 0 }; }
  const o = phase < 0.3 ? -1.2 - 0.25 * (phase / 0.3) : phase < 0.5 ? -1.45 + 2.0 * ((phase - 0.3) / 0.2) : 0.55 * (1 - (phase - 0.5) / 0.5);
  return { off: o, lean: phase < 0.3 ? -1 : phase < 0.7 ? 1 : 0, reach: 0 };
}

export interface PlayerLike {
  x: number; y: number; vx: number; vy: number; face: 1 | -1; onGround: boolean; inWater: number; alive: boolean; sleeping: boolean; hurtT: number; core: number;
  h: number; frost: { face: number }; anim: { state: string; t: number };
}
export interface HeldLike { item: string | null; aim: number; swing: number; using: boolean; load?: number }

export function rimeLevel(core: number, faceFrost: number): 0 | 1 | 2 {
  return faceFrost >= 70 || core < 33.5 ? 2 : faceFrost >= 30 || core < 35.4 ? 1 : 0;
}

/** Decide the pose from the game state. `t` = seconds. */
export function poseFor(p: PlayerLike, h: HeldLike, t: number, out: PoseSpec = newPose()): PoseSpec {
  const s = out; Object.assign(s, newPose());
  s.face = p.face; s.t = t; s.rime = rimeLevel(p.core, p.frost.face);
  if (!p.alive) { s.lying = 'dead'; return s; }
  if (p.sleeping) { s.lying = 'sleep'; return s; }
  const st = p.anim.state, speed = Math.abs(p.vx);
  s.hurt = p.hurtT > 0.25 || st === 'hurt';
  const swim = st === 'swim' || p.inWater > 0.45;
  let armSwing = 0;
  if (swim) {
    s.legs = Math.floor(t * 4) % 2 ? 'kick1' : 'kick0'; s.clipH = Math.max(3, Math.round(p.h * (1 - p.inWater * 0.85) + 3)); s.dy = Math.floor(t * 2) % 2 ? 0 : 1;
    s.far = 'fwd'; s.lean = 1;
  } else if (!p.onGround) {
    s.legs = p.vy < 0 ? 'jump' : 'fall'; s.far = p.vy < 0 ? 'up' : 'fwd'; s.lean = p.vy < 0 ? 0 : 0; s.headDy = p.vy < 0 ? 0 : 1;
  } else if (speed > 3) {
    const run = st === 'run' || speed > 52;
    const ph = (((p.x * p.face) / (run ? 14 : 11)) % 1 + 1) % 1, fr = Math.floor(ph * 4);
    s.legs = (run ? 'run' : 'walk') + fr;
    const d = LEGS[s.legs]; armSwing = -d[2] * (run ? 1.2 : 0.9);
    s.far = d[0] > 0.5 ? 'fwd' : d[0] < -0.5 ? 'back' : 'down';
    s.dy = run ? (fr % 2 ? -1 : 0) : (fr % 2 ? -1 : 0); s.lean = run ? 1 : 0; s.headDy = 0;
  } else {
    const br = Math.floor(t * 1.15) % 2;
    s.legs = 'stand'; s.headDy = br; s.far = 'down';
  }
  if (p.core < 35.0 && p.onGround && speed < 3 && !swim) { // shiver
    s.shakeX = Math.floor(t * 22) % 2 ? 1 : 0; s.far = 'hug'; s.hand = [4, -8]; s.headDy = 1;
  }
  if (s.hurt) { s.lean = -1; s.far = 'up'; s.hand = [2, -15]; }

  // ---- hands / tools ----
  const it = h.item;
  if (it === 'snow_block') {
    s.carry = true; s.far = 'up'; s.armBehind = true; s.hand = [3, -19 + s.dy]; s.headDy = Math.max(s.headDy, 0);
  } else if (it && HELD[it] && !s.hurt) {
    const def = HELD[it];
    const aimLocal = p.face > 0 ? h.aim : Math.PI - h.aim;
    let a = Math.atan2(Math.sin(aimLocal), Math.cos(aimLocal));
    let reach = ARM_LEN, off = 0;
    const moving = speed > 3 && p.onGround;
    let phase = -1;
    if (h.using) phase = (t * 3.2) % 1; else if (h.swing > 0.02) phase = 1 - h.swing;
    if (def.swing === 'saw' && h.using) {
      reach += Math.sin(t * 17) * 2.4; s.lean = 1; s.headDy = Math.max(s.headDy, 0);
    } else if (phase >= 0 && def.swing !== 'none' && def.swing !== 'hang') {
      const k = def.swing === 'saw' ? 'chop' : def.swing === 'wave' ? 'chop' : def.swing;
      const so = swingOffset(phase, k);
      off = so.off; reach += so.reach; s.lean = so.lean; if (!moving) s.legs = 'stand';
    } else if (def.swing === 'none' && h.swing > 0.02) reach -= 2 * h.swing;   // recoil
    a = ang2(a + off);
    if (def.swing === 'wave') a = Math.min(a, -0.35);
    if (def.swing === 'hang') { a = Math.PI / 2; reach = 3.5; }
    const sx = SH_X + s.lean, sy = SH_Y + s.dy;
    const hx = sx + Math.cos(a) * reach + (def.swing === 'hang' ? 2 : 0), hy = sy + Math.sin(a) * reach;
    s.hand = [Math.round(hx), Math.round(hy)];
    s.tool = { item: it, ang: def.swing === 'hang' ? 0 : a, reach, load: h.load ?? 0, flipY: def.swing !== 'hang' && Math.cos(a) < 0, using: h.using, t };
  } else if (!s.hand && (h.using || h.swing > 0.02) && p.onGround) {
    // bare-handed work (placing, eating): small reaching motion
    const ph = 0.5 + 0.5 * Math.sin(t * 12);
    s.hand = [Math.round(4 + ph * 2), Math.round(-9 - ph * 2)];
  }
  if (!s.hand) s.hand = [Math.round(1 + armSwing * 0.8), -6 + (s.dy ? 1 : 0)];
  return s;
}

/** Draw a pose with its feet-centre at (ax, ay) in view cells. */
export function renderPose(ctx: CanvasRenderingContext2D, ax: number, ay: number, s: PoseSpec, look: Look, sp?: { flash?: boolean }) {
  const pal = palette(look);
  ax = Math.round(ax) + s.shakeX; ay = Math.round(ay);
  ctx.save();
  ctx.translate(ax, ay); ctx.scale(s.face, 1);
  if (s.clipH !== null) { ctx.beginPath(); ctx.rect(-24, -48, 48, 48 - s.clipH); ctx.clip(); }
  if (s.lying) {
    const c = lyingCanvas(look, s.lying, s.rime);
    const bob = s.lying === 'sleep' ? (Math.floor(s.t * 0.8) % 2) : 0;
    ctx.drawImage(c, -Math.floor(c.width / 2), -c.height - (s.lying === 'sleep' ? 1 : 0) + 0);
    if (s.lying === 'sleep') drawZz(ctx, s.t, c.width / 2 - 4, -c.height - 2 - bob);
    ctx.restore(); return;
  }
  const bk: BodyKey = { legs: s.legs, lean: s.lean, headDy: s.headDy, far: s.far, rime: s.rime, torsoDy: s.torsoDy };
  const body = bodyCanvas(look, bk);
  const sx = SH_X + s.lean, sy = SH_Y + s.dy;
  const hand: [number, number] = s.hand ?? [1, -6];
  const drawTool = () => {
    const tl = s.tool; if (!tl) return;
    const def = HELD[tl.item]; if (!def) return;
    ctx.save(); ctx.translate(hand[0], hand[1]); ctx.rotate(tl.ang); if (tl.flipY) ctx.scale(1, -1);
    ctx.translate(-def.gx, -def.gy);
    drawSprite(ctx, def.key, 0, 0);
    if (tl.item === 'shovel' && tl.load > 0.04) {
      const k = Math.min(1, tl.load), hh = 1 + Math.round(k * 3), wd = 4 + (k > 0.5 ? 1 : 0);
      for (let j = 0; j < hh; j++) { const w = Math.max(2, wd - j); ctx.fillStyle = j === hh - 1 ? '#ffffff' : j === 0 ? '#c3d3e6' : '#e8f1fb'; ctx.fillRect(13 + Math.floor((wd - w) / 2), 1 - 1 - j + 0, w, 1); }
    }
    ctx.restore();
    if (tl.item === 'fishing_line') {
      const tx = hand[0] + Math.cos(tl.ang) * (def.w - def.gx), ty = hand[1] + Math.sin(tl.ang) * (def.w - def.gx);
      ctx.fillStyle = '#dfe9f4'; const len = 7 + Math.round(Math.sin(tl.t * 2) * 1);
      ctx.fillRect(Math.round(tx), Math.round(ty), 1, len); ctx.fillStyle = '#c9d3df'; ctx.fillRect(Math.round(tx), Math.round(ty) + len, 1, 1); ctx.fillRect(Math.round(tx) + 1, Math.round(ty) + len, 1, 1);
    }
  };
  if (s.armBehind) drawArm(ctx, look, sx, sy, hand[0] - 3, hand[1], pal);
  ctx.drawImage(body, -7, -21 + s.dy);
  if (sp?.flash || s.hurt && Math.floor(s.t * 24) % 2 === 0) {
    let sil = silCache.get(body); if (!sil) { sil = silhouette(body, '#ffb4a0'); silCache.set(body, sil); }
    ctx.globalAlpha = 0.6; ctx.drawImage(sil, -7, -21 + s.dy); ctx.globalAlpha = 1;
  }
  if (s.carry) {
    // snow block held above the head
    const bx = -3 + s.lean, by = -27 + s.dy;
    ctx.fillStyle = '#9fb3ca'; ctx.fillRect(bx - 1, by - 1, 12, 7);
    ctx.fillStyle = '#e6eff9'; ctx.fillRect(bx, by, 10, 5);
    ctx.fillStyle = '#ffffff'; ctx.fillRect(bx, by, 10, 1); ctx.fillRect(bx, by, 1, 5);
    ctx.fillStyle = '#c0d0e2'; ctx.fillRect(bx + 1, by + 4, 9, 1); ctx.fillRect(bx + 9, by + 1, 1, 4);
    ctx.fillStyle = '#d3e0ef'; ctx.fillRect(bx + 3, by + 2, 1, 1); ctx.fillRect(bx + 6, by + 1, 1, 1); ctx.fillRect(bx + 7, by + 3, 1, 1);
  }
  if (!s.armBehind) {
    if (s.tool) { drawArm(ctx, look, sx, sy, hand[0], hand[1], pal); drawTool(); drawHandOver(ctx, look, hand, pal); }
    else drawArm(ctx, look, sx, sy, hand[0], hand[1], pal);
  } else {
    drawArm(ctx, look, sx + 4, sy, hand[0] + 1, hand[1] + 1, pal);
  }
  if (s.tool && s.tool.item === 'torch') drawTorchFlame(ctx, hand, s.tool);
  ctx.restore();
}

function drawHandOver(ctx: CanvasRenderingContext2D, look: Look, hand: [number, number], pal: Palette) {
  const mit = look.hands === 'fur' ? 3 : 2, mx = hand[0] - (mit === 3 ? 1 : 0), my = hand[1] - (mit === 3 ? 1 : 0);
  for (let j = 0; j < mit; j++) for (let i = 0; i < mit; i++) pixelRect(ctx, j === mit - 1 || i === 0 ? pal.M : pal.m, mx + i, my + j);
}

function drawTorchFlame(ctx: CanvasRenderingContext2D, hand: [number, number], tl: ToolSpec) {
  const def = HELD.torch; if (!def) return;
  const tx = hand[0] + Math.cos(tl.ang) * (def.w - def.gx - 2), ty = hand[1] + Math.sin(tl.ang) * (def.w - def.gx - 2);
  ctx.save(); ctx.globalCompositeOperation = 'source-over';
  drawFlame(ctx, tx, ty, tl.t, 2, 6, 3.3, 1);
  ctx.restore();
}

function drawZz(ctx: CanvasRenderingContext2D, t: number, x: number, y: number) {
  const z = (ox: number, oy: number, sz: number, a: number) => {
    ctx.globalAlpha = a; ctx.fillStyle = '#dcecff';
    ctx.fillRect(ox, oy, sz, 1); ctx.fillRect(ox, oy + sz - 1, sz, 1);
    for (let i = 1; i < sz - 1; i++) ctx.fillRect(ox + sz - 1 - i, oy + i, 1, 1);
    ctx.globalAlpha = 1;
  };
  const k = (t * 0.7) % 1;
  z(Math.round(x + 2 + k * 3), Math.round(y - 3 - k * 6), 3, 1 - k);
  const k2 = (t * 0.7 + 0.5) % 1;
  z(Math.round(x + 5 + k2 * 4), Math.round(y - 6 - k2 * 7), 4, 1 - k2);
}

