export interface PoseEntry { name: string; build: (s: PoseSpec) => void; }
export const PLAYER_POSES: PoseEntry[] = [
  { name: 'idle 0', build: s => { s.headDy = 0; } },
  { name: 'idle 1', build: s => { s.headDy = 1; } },
  ...[0, 1, 2, 3].map(i => ({ name: 'walk ' + i, build: (s: PoseSpec) => { s.legs = 'walk' + i; s.far = LEGS['walk' + i][0] > 0 ? 'fwd' : LEGS['walk' + i][0] < 0 ? 'back' : 'down'; s.dy = i % 2 ? -1 : 0; s.hand = [Math.round(1 - LEGS['walk' + i][2] * 0.7), -6]; } })),
  ...[0, 1, 2, 3].map(i => ({ name: 'run ' + i, build: (s: PoseSpec) => { s.legs = 'run' + i; s.far = LEGS['run' + i][0] > 0 ? 'fwd' : LEGS['run' + i][0] < 0 ? 'back' : 'down'; s.dy = i % 2 ? -1 : 0; s.lean = 1; s.hand = [Math.round(1 - LEGS['run' + i][2] * 1.0), -6]; } })),
  { name: 'jump', build: s => { s.legs = 'jump'; s.far = 'up'; s.hand = [3, -16]; } },
  { name: 'fall', build: s => { s.legs = 'fall'; s.far = 'fwd'; s.headDy = 1; s.hand = [4, -15]; } },
  { name: 'swim 0', build: s => { s.legs = 'kick0'; s.far = 'fwd'; s.lean = 1; s.clipH = 7; s.hand = [5, -10]; } },
  { name: 'swim 1', build: s => { s.legs = 'kick1'; s.far = 'back'; s.lean = 1; s.clipH = 7; s.dy = 1; s.hand = [0, -8]; } },
  { name: 'hurt', build: s => { s.hurt = true; s.lean = -1; s.far = 'up'; s.hand = [2, -15]; } },
  { name: 'shiver', build: s => { s.far = 'hug'; s.hand = [4, -8]; s.headDy = 1; s.shakeX = 1; } },
  { name: 'sleep', build: s => { s.lying = 'sleep'; } },
  { name: 'dead', build: s => { s.lying = 'dead'; } },
];
export function clearPlayerCache() { bodyCache.clear(); lyingCache.clear(); }
void compose; void newCanvas;
